import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [file, setFile] = useState(null);
  const [jsonData, setJsonData] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async () => {
    if (!file) return;
    setLoading(true);
    const formData = new FormData();
    formData.append('pdf', file);

    try {
      const response = await axios.post('http://localhost:5000/processar-pdf', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setJsonData(response.data);
    } catch (error) {
      console.error(error);
      alert('Erro ao processar: ' + (error.response?.data?.error || 'Erro desconhecido'));
    }
    setLoading(false);
  };

  return (
    <div className="app-container">
      <h1 className="title">Processador de Nota Fiscal</h1>
      <div className="upload-container">
        <input
          type="file"
          accept=".pdf"
          onChange={handleFileChange}
          className="file-input"
        />
        <button
          onClick={handleSubmit}
          disabled={loading}
          className="submit-button"
        >
          {loading ? 'Processando...' : 'Extrair Dados'}
        </button>
      </div>
      {jsonData && (
        <div className="json-container">
          <h2 className="json-title">Dados Extraídos</h2>
          <div className="json-section">
            <h3>Fornecedor</h3>
            <p><strong>Razão Social:</strong> {jsonData.fornecedor.razaoSocial}</p>
            <p><strong>Fantasia:</strong> {jsonData.fornecedor.fantasia || 'N/A'}</p>
            <p><strong>CNPJ:</strong> {jsonData.fornecedor.cnpj}</p>
            <p><strong>Endereço:</strong> {jsonData.fornecedor.endereco.rua
              ? `${jsonData.fornecedor.endereco.rua}, ${jsonData.fornecedor.endereco.numero || ''}, ${jsonData.fornecedor.endereco.bairro || ''}, ${jsonData.fornecedor.endereco.cidade || ''} - ${jsonData.fornecedor.endereco.estado || ''}, ${jsonData.fornecedor.endereco.cep || ''}`
              : 'N/A'}</p>
          </div>
          <div className="json-section">
            <h3>Faturado</h3>
            <p><strong>Nome:</strong> {jsonData.faturado.nomeCompleto}</p>
            <p><strong>CPF:</strong> {jsonData.faturado.cpf || 'N/A'}</p>
            <p><strong>CNPJ:</strong> {jsonData.faturado.cnpj || 'N/A'}</p>
          </div>
          <div className="json-section">
            <h3>Nota Fiscal</h3>
            <p><strong>Número:</strong> {jsonData.numeroNotaFiscal}</p>
            <p><strong>Série:</strong> {jsonData.serieNota || 'N/A'}</p>
            <p><strong>Chave NF-e:</strong> {jsonData.chaveNfe || 'N/A'}</p>
            <p><strong>Data de Emissão:</strong> {jsonData.dataEmissao}</p>
          </div>
          <div className="json-section">
            <h3>Produtos</h3>
            <ul>
              {jsonData.produtos.map((produto, index) => (
                <li key={index}>
                  <p><strong>Código:</strong> {produto.codigo || 'N/A'}</p>
                  <p><strong>Descrição:</strong> {produto.descricao}</p>
                  <p><strong>Quantidade:</strong> {produto.quantidade}</p>
                  <p><strong>Valor Unitário:</strong> R$ {produto.valorUnitario.toFixed(2)}</p>
                  <p><strong>Valor Total:</strong> R$ {produto.valorTotal.toFixed(2)}</p>
                </li>
              ))}
            </ul>
          </div>
          <div className="json-section">
            <h3>Pagamento</h3>
            <p><strong>Quantidade de Parcelas:</strong> {jsonData.quantidadeParcelas}</p>
            <p><strong>Forma de Pagamento:</strong> {jsonData.formaPagamento || 'N/A'}</p>
            <h4>Parcelas</h4>
            <ul>
              {jsonData.parcelas.map((parcela, index) => (
                <li key={index}>
                  <p><strong>Parcela {parcela.numero}:</strong> Vencimento em {parcela.dataVencimento}, Valor: R$ {parcela.valor.toFixed(2)}</p>
                </li>
              ))}
            </ul>
          </div>
          <div className="json-section">
            <h3>Impostos</h3>
            <p><strong>ICMS:</strong> R$ {jsonData.icms.valor.toFixed(2)} (Alíquota: {jsonData.icms.aliquota || 'N/A'})</p>
          </div>
          <div className="json-section">
            <h3>Outros</h3>
            <p><strong>Valor Total:</strong> R$ {jsonData.valorTotal.toFixed(2)}</p>
            <p><strong>Classificação da Despesa:</strong> {jsonData.classificacaoDespesa}</p>
          </div>
          <div className="json-section">
            <h3>JSON Completo</h3>
            <pre className="json-output">{JSON.stringify(jsonData, null, 2)}</pre>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
